/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original binary (prog55_connected_components).
 * The program reads an even number of command‑line arguments, each pair
 * representing an undirected edge between vertices 0‑7.  It builds an
 * adjacency matrix, finds all connected components (including isolated
 * vertices) with a BFS, and prints them in the format used by the
 * original binary:
 *
 *     0: {0,1,2}
 *     1: {3,4}
 *     …
 *
 * If the input is malformed (odd number of arguments after the program
 * name, a vertex outside the range 0‑7, or a negative value) the program
 * prints the exact string "INVALID_INPUT" and exits with status 1.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8               /* vertices are 0‑7 */

int main(int argc, char **argv)
{
    /* --------------------------------------------------------------
       Input validation – the program expects an even number of
       arguments after the program name, each representing a vertex.
       -------------------------------------------------------------- */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    int adj[MAXV][MAXV] = {{0}};          /* adjacency matrix */
    int edges = (argc - 1) / 2;           /* number of edge pairs */

    for (int i = 0; i < edges; ++i) {
        char *endptr;
        long a = strtol(argv[1 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || a < 0 || a >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }
        long b = strtol(argv[2 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || b < 0 || b >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[a][b] = 1;
        adj[b][a] = 1;                     /* undirected edge */
    }

    /* --------------------------------------------------------------
       Connected‑components search (BFS).  The original binary iterates
       over all vertices 0‑7, starts a BFS for each unvisited vertex,
       stores the vertices of the current component, and prints the
       component number followed by the list of vertices.
       -------------------------------------------------------------- */
    int visited[MAXV] = {0};
    int queue[MAXV];
    int component_id = 0;                 /* component counter */

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;

        /* BFS initialisation */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = 1;

        int comp_vertices[MAXV];
        int comp_size = 0;

        while (qhead < qtail) {
            int v = queue[qhead++];
            comp_vertices[comp_size++] = v;

            for (int w = 0; w < MAXV; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = 1;
                    queue[qtail++] = w;
                }
            }
        }

        /* ----- printing the component ----- */
        printf("%d:", component_id);
        printf(" {");
        for (int i = 0; i < comp_size; ++i) {
            if (i > 0)
                putchar(',');
            printf("%d", comp_vertices[i]);
        }
        putchar('}');
        putchar('\n');

        ++component_id;
    }

    return 0;
}
